import * as OurStringification from "../src/stringification";
import * as OurTypes from "../src/types";

test("Color stringification round-trip Red", () => {
  const literal = OurTypes.Color.Red;

  const text = OurStringification.mustColorToString(literal);
  expect(text).toStrictEqual("red");

  const nullableText = OurStringification.colorToString(literal);
  expect(nullableText).toStrictEqual("red");

  const parsed = OurStringification.colorFromString(text);
  expect(parsed).toStrictEqual(literal);
});

