test("Color from invalid string", () => {
  const parsed = OurStringification.colorFromString(
    "invalid-literal"
  );

  expect(parsed).toBeNull();
});

test("Color invalid literal to string", () => {
  // The number 9007199254740991 is the maximum safe integer.
  const invalidLiteral = <OurTypes.Color>9007199254740991;

  expect(OurStringification.colorToString(invalidLiteral)).toBeNull();
  expect(() => OurStringification.mustColorToString(invalidLiteral)).toThrow();
});

